import math

results = []

for p in range(1, 5):
    # Calculate the maximum m such that p^6 - 1 - m^3 >= 0
    upper_bound_m = math.ceil((p**6 - 1)**(1/3))

    print(f"--- Checking p = {p} ---")

    for m in range(1, upper_bound_m + 1):
        X = p**6 - 1 - m**3

        if X < 0:
            # Should not happen if upper_bound_m is calculated correctly, but safe check
            break

        # Check if X is a perfect square
        n = int(math.isqrt(X))
        if n * n == X:
            results.append({
                "p": p,
                "m": m,
                "X": X,
                "n": n
            })
            print(f"Found solution for p={p}, m={m}: {X} = {n}^2")
        # else:
            # print(f"p={p}, m={m}: {X} (Not a square)")

print("\n--- Summary ---")
if results:
    for res in results:
        print(f"p={res['p']}, m={res['m']}, X={res['X']}, n={res['n']}")
else:
    print("No solutions found.")
